<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'names')); $types=wp_get_post_terms($id,'bsktv_type',array('fields'=>'names')); $line_url=get_theme_mod('bsktv_line_url',''); ?>
<main class="single-page"><article>
<header class="store-hero-detail"><div class="store-hero-image"><?php if(has_post_thumbnail())the_post_thumbnail('full',array('fetchpriority'=>'high'));else echo '<div class="store-card-placeholder">BSKTV</div>'; ?><div class="store-hero-overlay"></div></div><div class="container store-hero-content"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">首頁</a><span>/</span><?php echo esc_html(implode('、',$cities)); ?></div><div class="store-kicker"><?php echo esc_html(implode(' · ',$types)); ?></div><h1><?php the_title(); ?></h1><?php if($p=bsktv_meta('bsktv_price'))echo '<div class="hero-price">'.esc_html($p).'</div>'; ?><div class="hero-actions"><button class="btn btn-gold" type="button" data-favorite data-id="<?php echo esc_attr($id); ?>">♡ 收藏店家</button></div></div></header>
<div class="container section"><div class="single-layout"><div class="article-main"><div class="article-meta"><span>更新於 <?php echo esc_html(get_the_modified_date()); ?></span><span><?php echo esc_html(bsktv_views($id)); ?> 次瀏覽</span></div><div class="article-content"><?php the_content(); ?></div>
</div><aside class="store-info"><div class="info-sticky"><div class="info-title"><span class="eyebrow">STORE INFO</span><h2>店家資訊</h2></div><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_model'=>'坐檯模式','bsktv_room_price'=>'包廂費用','bsktv_host_price'=>'少爺費用','bsktv_head_price'=>'人頭費用','bsktv_lady_price'=>'小姐費用','bsktv_manager_price'=>'幹部費用');foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v!==''){$is_price=in_array($k,array('bsktv_room_price','bsktv_host_price','bsktv_head_price','bsktv_lady_price','bsktv_manager_price'),true);echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span><span>'.($is_price?'NT$ '.esc_html(number_format_i18n((float)$v)):esc_html($v)).'</span></div>';}} echo '<a class="btn btn-primary btn-full" href="'.esc_url($line_url).'" target="_blank" rel="noopener noreferrer">聯絡幹部</a>'; ?></div></aside></div></div></article><?php get_template_part('template-parts/related'); ?></main><?php endwhile; get_footer(); ?>
